// Источник: web-тест .qa/e2e/tests/nusach-switch/ns-02-missing-section-fallback.spec.ts, план .qa/e2e/specs/nusach-switch.md, кейс .qa/tests/nusach-switch/NS-02-switch-keeps-position.md
// Тикет #6a86f7d8 «פיתוח: החלפת נוסח בתוך התפילה». Опора: F-37 AC2, AC3 · S-33 AC1–AC4.
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabelStartsWith, tapText, expectVisibleText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

/** מנחה ספרד: deep link, иначе «תפילות» → «מנחה» (нусах профиля אשכנז) → меню нусаха → «ספרדי» → «החלף». */
async function openMinchaSfarad() {
  if (hasDeepLinks()) {
    await openRoute('/prayer/mincha_sfarad');
  } else {
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('ספרדי');
    const replace = await byText('החלף');
    if (await replace.isDisplayed().catch(() => false)) await replace.click();
  }
  await expectVisibleText('מנחה (ספרדי)');
  await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();
}

/** Текст экрана (атрибуты text/label из дерева элементов), нормализованный в NFC — порядок огласовок может отличаться. */
async function screenTextNFC() {
  const src = await driver.getPageSource();
  return src.normalize('NFC');
}

describe('Смена нусаха внутри молитвы', () => {
  afterEach(async () => { await toHome(); });

  it('NS-02 Фрагмента нет в другом нусахе → переход к следующему с пояснением #6a86f7d8 @prod-safe', async () => {
    // 1. מנחה (ספרדי), «1 מתוך 11» — секция «קרבנות».
    await openMinchaSfarad();
    await goToPage(1, 11);
    expect(await pageCounter()).toBe('1 מתוך 11');
    await expectVisibleText('קרבנות');

    // 2. Меню нусаха → «אשכנזי» — окно с пояснением, что «קרבנות» нет в נוסח אשכנז.
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('אשכנזי');
    await expect(byTextContains('הקטע ״קרבנות״ אינו קיים בנוסח אשכנז. התפילה תמשיך מהקטע ״אשרי״')).toBeDisplayed();

    // 3. «החלף» — מנחה (אשכנזי), секция «אשרי», текст секции не пустой.
    await tapText('החלף');
    await expectVisibleText('מנחה (אשכנזי)');
    await expectVisibleText('אשרי');
    const expected = 'אַשְׁרֵי יוֹשְׁ֒בֵי בֵיתֶֽךָ'.normalize('NFC');
    await driver.waitUntil(async () => (await screenTextNFC()).includes(expected), {
      timeoutMsg: 'Нет текста секции «אשרי» после смены нусаха',
    });
    // Итог — נוסח אשכנז (как у профиля), возвращать нечего.
  });
});
